new='''<div class="app">\n  <header>\n    <button class="cinema-menu-toggle" id="cinemaMenuToggle" type="button" aria-label="メニューを開く" aria-controls="cinemaNav" aria-expanded="false">☰</button>\n    <div class="brand"><div class="brand-kicker">PRIVATE CINEMA ARCHIVE</div><h1><span class="brand-mark" aria-hidden="true">◉</span> シネマ蔵書館</h1><p>映画で、また会える。</p></div>\n    <div class="header-actions"><div><div class="user" id="currentUser"></div><div class="stats" id="stats">読み込み中...</div><div class="scan-status" id="scanStatus"></div></div><button class="ghost" id="scanButton">再スキャン</button></div>\n  </header>\n  <aside class="cinema-nav" id="cinemaNav" aria-label="シネマ蔵書館メニュー"><div class="cinema-nav-inner"><div class="cinema-nav-title">館内案内<small>CINEMA DIRECTORY</small></div><nav class="cinema-nav-list">\n    <button class="cinema-nav-item active" type="button" data-cinema-nav="continue"><span class="cinema-nav-icon">●</span><span class="cinema-nav-label">上映中<small>いま観られる作品</small></span></button>\n    <button class="cinema-nav-item" type="button" data-cinema-nav="next"><span class="cinema-nav-icon">▣</span><span class="cinema-nav-label">次回上映<small>次に観る一本</small></span></button>\n    <button class="cinema-nav-item" type="button" data-cinema-nav="catalog"><span class="cinema-nav-icon">▤</span><span class="cinema-nav-label">作品目録<small>すべての作品</small></span></button>\n    <button class="cinema-nav-item" type="button" data-cinema-nav="people"><span class="cinema-nav-icon">●●</span><span class="cinema-nav-label">俳優・監督検索<small>人物名から探す</small></span></button>\n    <button class="cinema-nav-item" type="button" data-cinema-nav="diagnostics"><span class="cinema-nav-icon">☆</span><span class="cinema-nav-label">診断の部屋<small>ライブラリ状態</small></span></button>\n    <button class="cinema-nav-item" type="button" data-cinema-nav="scan"><span class="cinema-nav-icon">↻</span><span class="cinema-nav-label">再スキャン<small>蔵書を再確認</small></span></button>\n  </nav></div></aside>\n  <div class="cinema-drawer-backdrop" id="cinemaDrawerBackdrop" aria-hidden="true"></div>\n  <main>'''
