old_footer='''  <footer class="tmdb-credit">This product uses the TMDB API but is not endorsed or certified by TMDB. · <a href="https://www.themoviedb.org" target="_blank" rel="noopener noreferrer">TMDB</a></footer>\n</div>'''
new_footer='''  <footer class="tmdb-credit"><span class="cinema-footer-motto">映画は、人生のよき友だ。</span><span class="cinema-footer-mark">CINEMA ◉ ARCHIVE</span>This product uses the TMDB API but is not endorsed or certified by TMDB. · <a href="https://www.themoviedb.org" target="_blank" rel="noopener noreferrer">TMDB</a></footer>\n</div>\n<nav class="cinema-mobile-nav" aria-label="モバイルナビ"><button type="button" data-cinema-nav="continue"><span>●</span>上映中</button><button type="button" data-cinema-nav="next"><span>▣</span>次回上映</button><button type="button" data-cinema-nav="catalog"><span>▤</span>作品目録</button><button type="button" data-cinema-nav="menu"><span>☰</span>メニュー</button></nav>'''
if old_footer not in s: raise SystemExit('footer anchor not found')
s=s.replace(old_footer,new_footer)

js=r'''
function setCinemaDrawer(open){const nav=$('cinemaNav'),back=$('cinemaDrawerBackdrop'),toggle=$('cinemaMenuToggle');if(!nav||!back||!toggle)return;nav.classList.toggle('open',!!open);back.classList.toggle('open',!!open);toggle.setAttribute('aria-expanded',open?'true':'false');document.body.classList.toggle('cinema-drawer-open',!!open)}
function cinemaScrollTo(id){if(location.hash&&!location.hash.startsWith('#/library'))location.hash='#/library';setTimeout(()=>{const el=$(id);if(el&&!el.hidden)el.scrollIntoView({behavior:'smooth',block:'start'})},80)}
function runCinemaNav(action){setCinemaDrawer(false);document.querySelectorAll('.cinema-nav-item').forEach(x=>x.classList.toggle('active',x.dataset.cinemaNav===action));if(action==='continue'){cinemaScrollTo('continueSection');return}if(action==='next'){cinemaScrollTo('nextSection');return}if(action==='catalog'){cinemaScrollTo('catalog');return}if(action==='people'){cinemaScrollTo('catalog');setTimeout(()=>{const q=$('search');if(q){q.focus();q.placeholder='俳優・監督名を入力...'}},120);return}if(action==='diagnostics'){location.href='/diagnostics.html';return}if(action==='scan'){runScan();return}if(action==='menu'){setCinemaDrawer(true)}}
function setupCinemaShell(){const toggle=$('cinemaMenuToggle'),back=$('cinemaDrawerBackdrop');if(toggle)toggle.onclick=()=>setCinemaDrawer(!($('cinemaNav')?.classList.contains('open')));if(back)back.onclick=()=>setCinemaDrawer(false);document.querySelectorAll('[data-cinema-nav]').forEach(b=>b.addEventListener('click',()=>runCinemaNav(b.dataset.cinemaNav||'')));window.addEventListener('resize',()=>{if(window.innerWidth>=1200)setCinemaDrawer(false)},{passive:true});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('cinemaNav')?.classList.contains('open'))setCinemaDrawer(false)})}
'''
anchor="function phaseLabel(p){return({PREPARING:'準備中'"
if js.strip() not in s:
    i=s.find(anchor)
    if i<0: raise SystemExit('js anchor not found')
    s=s[:i]+js+'\n'+s[i:]

old_init="(async()=>{await Promise.all([loadStats(),loadUser(),loadScan(),loadHome()]);route()})();"
new_init="(async()=>{setupCinemaShell();await Promise.all([loadStats(),loadUser(),loadScan(),loadHome()]);route()})();"
if old_init not in s: raise SystemExit('init anchor not found')
s=s.replace(old_init,new_init)
p.write_text(s,encoding='utf-8')

# documentation
Path('docs/58-1.1.0-responsive-image-cinema-shell.md').write_text('''# 1.1.0 シネマ蔵書館 画像装飾レスポンシブシェル\n\nIssue #130。Run #185 のデザインを、確認済みモックアップへさらに近づける。\n\n## 方針\n- 文字・操作要素はHTMLのまま保持する。\n- 赤い幕、木枠、真鍮、照明、映画館外観、フッター布地はSVG画像としてCSSへ埋め込む。\n- 追加の外部画像ファイルを必要としないため、PyInstaller/Installerの同梱漏れを防ぐ。\n\n## レスポンシブ\n- PC 1200px以上: 左サイドメニュー常設、フルヘッダー、装飾フッター。\n- Tablet 768-1199px: サイドメニューをドロワー化。ヘッダーを圧縮。\n- Smartphone 767px以下: 1カラム、ドロワー、下部4ボタンナビ、コンパクトヘッダー。\n\n## メニュー\n上映中、次回上映、作品目録、俳優・監督検索、診断、再スキャン。既存機能へ接続し、新規DB/APIは追加しない。\n\n## 非変更\n再生、TMDb、人物リンク、お気に入り、検索API、DBスキーマ、表示バージョン1.1.0。\n''',encoding='utf-8')

Path('tests/test_cinema_library_responsive_image_shell_v110.py').write_text('''from pathlib import Path\nimport unittest\n\nROOT=Path(__file__).resolve().parents[1]\nHTML=(ROOT/'windows-installer'/'src'/'video-library.html').read_text(encoding='utf-8')\n\nclass ResponsiveImageShellTests(unittest.TestCase):\n    def test_image_shell_marker_and_svg_images(self):\n        self.assertIn('CINEMA_LIBRARY_RESPONSIVE_IMAGE_SHELL_V1',HTML)\n        self.assertGreaterEqual(HTML.count('data:image/svg+xml'),3)\n    def test_desktop_sidebar_and_navigation(self):\n        self.assertIn('id="cinemaNav"',HTML)\n        self.assertIn('data-cinema-nav="continue"',HTML)\n        self.assertIn('data-cinema-nav="next"',HTML)\n        self.assertIn('data-cinema-nav="catalog"',HTML)\n        self.assertIn("location.href='/diagnostics.html'",HTML)\n    def test_tablet_and_phone_breakpoints(self):\n        self.assertIn('@media(max-width:1199px)',HTML)\n        self.assertIn('@media(max-width:767px)',HTML)\n        self.assertIn('cinema-mobile-nav',HTML)\n        self.assertIn('cinema-drawer-backdrop',HTML)\n    def test_drawer_accessibility_and_keyboard(self):\n        self.assertIn('aria-controls="cinemaNav"',HTML)\n        self.assertIn("toggle.setAttribute('aria-expanded'",HTML)\n        self.assertIn("e.key==='Escape'",HTML)\n    def test_existing_features_remain(self):\n        self.assertIn("const PAGE=60",HTML)\n        self.assertIn("FEATURE PRESENTATION",HTML)\n        self.assertIn("posterFallback",HTML)\n        self.assertIn("creditRow",HTML)\n        self.assertIn("runScan",HTML)\n        self.assertIn("/api/me/works/${w.id}/favorite",HTML)\n\nif __name__=='__main__':unittest.main()\n''',encoding='utf-8')
